import { p256 } from '@noble/curves/nist.js';
import { sha256 } from '@noble/hashes/sha2.js';
import { parseCertificateChain } from '@ashaveri/attest-core';
import type { TestVendor } from '@ashaveri/fixtures';

/**
 * A DER `CertificateList` writer for the cases in `crl.test.ts`.
 *
 * Every list here is signed with a key generated by the test that asks for it, over the issuer certificate
 * `@ashaveri/fixtures` made for the same run. Nothing vendor-authored is stored: the members the writer
 * emits are the ASN.1 members RFC 5280 names, and the served shape those members describe is cited in
 * `intel-origin.ts`.
 */
export interface CrlEntryInput {
  /** The serial as hex text, which the writer encodes as the DER INTEGER it names. */
  readonly serial: string;
  /** Unix seconds at which the entry says the revocation took effect. */
  readonly revokedAt: number;
  /** A cRLReason code, or absent where the entry states no reason. */
  readonly reason?: number;
  /** Pad the serial INTEGER with a leading zero it does not need, which strict DER refuses. */
  readonly redundantSerialZero?: boolean;
  /** An unknown critical extension beside the reason, for a case that asks what the reader does with one. */
  readonly unknownCriticalExtension?: boolean;
  /** An unknown non-critical extension beside the reason, which a reader may skip. */
  readonly unknownExtension?: boolean;
}

export interface CrlInput {
  readonly vendor: TestVendor;
  readonly thisUpdate: number;
  readonly nextUpdate: number;
  readonly revoked?: readonly CrlEntryInput[];
  /** A key other than the vendor's issuing key, which makes a well-formed list that the chain did not sign. */
  readonly signingKey?: Uint8Array;
  /** The algorithm both identifiers name, so a case can ask what an unsupported suite is refused with. */
  readonly algorithmOid?: string;
  /** Leave `nextUpdate` out, which is a list that states no end to its own window. */
  readonly omitNextUpdate?: boolean;
  /** Leave the version INTEGER out, which is the DER spelling of version 1. */
  readonly omitVersion?: boolean;
  /** Bytes after the outer sequence, which a strict reader refuses. */
  readonly trailing?: Uint8Array;
}

const OID_ECDSA_SHA256 = '1.2.840.10045.4.3.2';
const OID_CRL_REASON = '2.5.29.21';
const OID_CRL_NUMBER = '2.5.29.20';
const OID_UNKNOWN = '1.2.3.4.5';

/** One whole `CertificateList`, signed over its own `tbsCertList`. */
export function writeCrl(input: CrlInput): Uint8Array {
  const vendor = input.vendor;
  const issuer = parseCertificateChain(vendor.issuerDer)[0];
  if (issuer === undefined) {
    throw new Error('the test vendor presents no issuer certificate');
  }
  const algorithm = sequence(oidNode(input.algorithmOid ?? OID_ECDSA_SHA256));
  const entries = (input.revoked ?? []).map((entry) => revokedEntry(entry));
  const tbs = sequence(
    ...(input.omitVersion ? [] : [integerSmall(1)]),
    algorithm,
    sequence(issuer.subject),
    timeNode(input.thisUpdate),
    ...(input.omitNextUpdate ? [] : [timeNode(input.nextUpdate)]),
    ...(entries.length === 0 ? [] : [sequence(...entries)]),
    // CRL number, non-critical, which the served list also carries and this reader skips.
    tlv(0xa0, sequence(extensionNode(OID_CRL_NUMBER, false, octetNode(integerSmall(1))))),
  );
  const signature = p256.sign(sha256(tbs), input.signingKey ?? vendor.signingKey).toBytes('der');
  return concat([sequence(tbs, algorithm, bitStringNode(signature)), input.trailing ?? new Uint8Array(0)]);
}

function revokedEntry(input: CrlEntryInput): Uint8Array {
  const extensions: Uint8Array[] = [];
  if (input.reason !== undefined) {
    extensions.push(extensionNode(OID_CRL_REASON, false, tlv(0x0a, Uint8Array.of(input.reason))));
  }
  if (input.unknownExtension === true) {
    extensions.push(extensionNode(OID_UNKNOWN, false, octetNode(tlv(0x04, Uint8Array.of(1)))));
  }
  if (input.unknownCriticalExtension === true) {
    extensions.push(extensionNode(OID_UNKNOWN, true, octetNode(tlv(0x04, Uint8Array.of(1)))));
  }
  return sequence(
    serialInteger(input.serial, input.redundantSerialZero === true),
    timeNode(input.revokedAt),
    ...(extensions.length === 0 ? [] : [sequence(...extensions)]),
  );
}

function extensionNode(oid: string, critical: boolean, value: Uint8Array): Uint8Array {
  return sequence(
    oidNode(oid),
    ...(critical ? [booleanNode(true)] : []),
    octetNode(value),
  );
}

function serialInteger(hex: string, redundantZero = false): Uint8Array {
  if (!/^[0-9a-fA-F]+$/u.test(hex)) {
    throw new Error(`serial ${hex} is not hex text`);
  }
  const padded = hex.length % 2 === 0 ? hex : `0${hex}`;
  let bytes: number[] = [];
  for (let at = 0; at < padded.length; at += 2) {
    bytes.push(Number.parseInt(padded.slice(at, at + 2), 16));
  }
  while (bytes.length > 1 && bytes[0] === 0) {
    bytes = bytes.slice(1);
  }
  if ((bytes[0] as number) >= 0x80) {
    bytes.unshift(0);
  }
  if (redundantZero) {
    bytes.unshift(0);
  }
  return tlv(0x02, Uint8Array.from(bytes));
}

function integerSmall(value: number): Uint8Array {
  const bytes: number[] = [];
  let rest = value;
  do {
    bytes.unshift(rest & 0xff);
    rest = Math.floor(rest / 256);
  } while (rest > 0);
  if ((bytes[0] as number) >= 0x80) {
    bytes.unshift(0);
  }
  return tlv(0x02, Uint8Array.from(bytes));
}

function oidNode(dotted: string): Uint8Array {
  const arcs = dotted.split('.').map((arc) => Number(arc));
  const first = arcs[0] ?? 0;
  const second = arcs[1] ?? 0;
  const bytes: number[] = [first * 40 + second];
  for (const arc of arcs.slice(2)) {
    const encoded: number[] = [];
    let rest = arc;
    do {
      encoded.unshift(rest & 0x7f);
      rest = Math.floor(rest / 128);
    } while (rest > 0);
    for (let index = 0; index < encoded.length; index += 1) {
      bytes.push(index === encoded.length - 1 ? (encoded[index] as number) : (encoded[index] as number) | 0x80);
    }
  }
  return tlv(0x06, Uint8Array.from(bytes));
}

function timeNode(seconds: number): Uint8Array {
  const at = new Date(seconds * 1000);
  const part = (value: number) => String(value).padStart(2, '0');
  const year = at.getUTCFullYear();
  const body = `${part(at.getUTCMonth() + 1)}${part(at.getUTCDate())}${part(at.getUTCHours())}${part(at.getUTCMinutes())}${part(at.getUTCSeconds())}Z`;
  return year >= 1950 && year <= 2049
    ? tlv(0x17, utf8(`${part(year % 100)}${body}`))
    : tlv(0x18, utf8(`${String(year).padStart(4, '0')}${body}`));
}

function booleanNode(value: boolean): Uint8Array {
  return tlv(0x01, Uint8Array.of(value ? 0xff : 0x00));
}

function octetNode(content: Uint8Array): Uint8Array {
  return tlv(0x04, content);
}

function bitStringNode(bits: Uint8Array): Uint8Array {
  return tlv(0x03, concat([Uint8Array.of(0), bits]));
}

function sequence(...parts: readonly Uint8Array[]): Uint8Array {
  return tlv(0x30, concat(parts));
}

function tlv(tag: number, content: Uint8Array): Uint8Array {
  const length = content.byteLength;
  if (length < 0x80) {
    return concat([Uint8Array.of(tag, length), content]);
  }
  const encoded: number[] = [];
  let rest = length;
  while (rest > 0) {
    encoded.unshift(rest & 0xff);
    rest = Math.floor(rest / 256);
  }
  return concat([Uint8Array.of(tag, 0x80 | encoded.length, ...encoded), content]);
}

function concat(parts: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((total, part) => total + part.byteLength, 0));
  let at = 0;
  for (const part of parts) {
    out.set(part, at);
    at += part.byteLength;
  }
  return out;
}

function utf8(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}
